#![warn(clippy::all, clippy::pedantic, clippy::nursery)]
use anyhow::Result;
use clap::Parser;
use figment::Figment;
use figment::providers::{Env, Format, Toml};
use rustical::config::Config;
use rustical::{Args, Command};
use rustical::{cmd_gen_config, cmd_health, cmd_principals, cmd_serve, cmd_share};
use tracing::warn;

fn env_provider() -> Env {
    Env::prefixed("RUSTICAL_")
        .split("__")
        // These names can be generated by Kubernetes
        // https://kubernetes.io/docs/concepts/services-networking/service/#environment-variables
        .filter(|k| !k.starts_with("SERVICE") && !k.starts_with("PORT"))
}

#[tokio::main(flavor = "multi_thread")]
async fn main() -> Result<()> {
    let args = Args::parse();

    let parse_config = || {
        Figment::new()
            .merge(Toml::file(&args.config_file))
            .merge(env_provider())
            .extract()
            // Clippy appeasement clippy::result_large_err
            .map_err(anyhow::Error::from)
    };

    match args.command {
        Command::GenConfig(gen_config_args) => cmd_gen_config(gen_config_args),
        Command::Principals(principals_args) => {
            cmd_principals(principals_args, parse_config()?).await
        }
        Command::Share(share_args) => cmd_share(share_args, parse_config()?).await,
        Command::Health(health_args) => {
            let config: Config = parse_config()?;
            cmd_health(config.http, health_args).await
        }
        Command::Serve => {
            let config: Config = parse_config()?;
            cmd_serve(args, config, None, true).await
        }
    }
}

#[cfg(test)]
mod test_config {
    use figment::{
        Figment, Jail,
        providers::{Format, Toml},
    };
    use rstest::rstest;
    use rustical::config::{Config, HttpBindConfig};

    use crate::env_provider;

    #[test]
    fn test_config_toml_http_host() {
        let config = r#"
[data_store.sqlite]
db_url = "/var/lib/rustical/db.sqlite3"

[http]
host = "0.0.0.0"
port = 4000

[oidc]
name = "Authelia"
issuer = "https://auth.rustical.dev"
client_id = "rustical"
client_secret = "secret"
claim_userid = "email"
scopes = ["openid", "email", "profile", "groups"]
require_group = "app:rustical"
allow_sign_up = true
"#;

        let config: Config = Figment::new()
            .merge(Toml::string(config))
            .extract()
            .unwrap();
        assert_eq!(
            config.http.bind_config().unwrap(),
            HttpBindConfig::Tcp("0.0.0.0:4000".to_string())
        );
    }

    #[test]
    fn test_config_env_http_host() {
        #[allow(clippy::result_large_err)]
        Jail::expect_with(|jail| {
            jail.set_env(
                "RUSTICAL_DATA_STORE__SQLITE__DB_URL",
                "/var/lib/rustical/db.sqlite3",
            );
            jail.set_env("RUSTICAL_HTTP__HOST", "localhost");
            jail.set_env("RUSTICAL_HTTP__PORT", "4000");

            let config: Config = Figment::new().merge(env_provider()).extract().unwrap();
            assert_eq!(
                config.http.bind_config().unwrap(),
                HttpBindConfig::Tcp("localhost:4000".to_string())
            );
            Ok(())
        });
    }

    #[test]
    fn test_config_toml_http_bind() {
        let config = r#"
[data_store.sqlite]
db_url = "/var/lib/rustical/db.sqlite3"

[http]
bind = "0.0.0.0:4000"

[oidc]
name = "Authelia"
issuer = "https://auth.rustical.dev"
client_id = "rustical"
client_secret = "secret"
claim_userid = "email"
scopes = ["openid", "email", "profile", "groups"]
require_group = "app:rustical"
allow_sign_up = true
"#;

        let config: Config = Figment::new()
            .merge(Toml::string(config))
            .extract()
            .unwrap();
        assert_eq!(
            config.http.bind_config().unwrap(),
            HttpBindConfig::Tcp("0.0.0.0:4000".to_string())
        );
    }

    #[test]
    fn test_config_env_http_bind() {
        #[allow(clippy::result_large_err)]
        Jail::expect_with(|jail| {
            jail.set_env(
                "RUSTICAL_DATA_STORE__SQLITE__DB_URL",
                "/var/lib/rustical/db.sqlite3",
            );
            jail.set_env("RUSTICAL_HTTP__BIND", "localhost:4000");

            let config: Config = Figment::new().merge(env_provider()).extract().unwrap();
            assert_eq!(
                config.http.bind_config().unwrap(),
                HttpBindConfig::Tcp("localhost:4000".to_string())
            );
            Ok(())
        });
    }

    #[test]
    fn test_config_env_http_unix() {
        #[allow(clippy::result_large_err)]
        Jail::expect_with(|jail| {
            jail.set_env(
                "RUSTICAL_DATA_STORE__SQLITE__DB_URL",
                "/var/lib/rustical/db.sqlite3",
            );
            jail.set_env("RUSTICAL_HTTP__BIND", "unix:/run/rustical/socket");

            let config: Config = Figment::new().merge(env_provider()).extract().unwrap();
            assert_eq!(
                config.http.bind_config().unwrap(),
                HttpBindConfig::Unix("/run/rustical/socket".parse().unwrap())
            );
            Ok(())
        });
    }

    #[rstest]
    #[case("RUSTICAL_SERVICE_HOST")]
    #[case("RUSTICAL_SERVICE_PORT")]
    #[case("RUSTICAL_PORT")]
    #[case("RUSTICAL_PORT_6379_TCP")]
    #[case("RUSTICAL_PORT_6379_TCP_PROTO")]
    #[case("RUSTICAL_PORT_6379_TCP_PORT")]
    #[case("RUSTICAL_PORT_6379_TCP_ADDR")]
    fn test_config_env_ignore_kubernetes(#[case] var: &str) {
        #[allow(clippy::result_large_err)]
        Jail::expect_with(|jail| {
            jail.set_env(
                "RUSTICAL_DATA_STORE__SQLITE__DB_URL",
                "/var/lib/rustical/db.sqlite3",
            );
            jail.set_env(var, "wat");

            Figment::new()
                .merge(env_provider())
                .extract::<Config>()
                .unwrap();
            Ok(())
        });
    }
}
